import numpy as np
from scipy.optimize import curve_fit, least_squares
data=[]
with open('graphene.dat') as f:
    for line in f:
        p=line.strip().split('\t')
        if len(p)==2: data.append([float(p[0].replace(',','.')),float(p[1].replace(',','.'))])
d=np.array(data); d=d[np.argsort(d[:,0])]
x,y=d[:,0],d[:,1]

def lor(x,off,A,x0,g): return off + A*g*g/((x-x0)**2+g*g)
def lorF(x,off,A,x0,gamma): return off + A*(gamma/2)**2/((x-x0)**2+(gamma/2)**2)
def gau(x,off,A,x0,s): return off + A*np.exp(-0.5*((x-x0)/s)**2)
def pvoigt(x,off,A,x0,w,eta):
    return off+A*(eta/(1+4*((x-x0)/w)**2)+(1-eta)*np.exp(-4*np.log(2)*((x-x0)/w)**2))
def linlor(x,off,slope,A,x0,g): return off+slope*(x-x0)+A*g*g/((x-x0)**2+g*g)

for name,x0p,amp in [('G',3745,11000),('2D',6329,7500)]:
  print('\n===',name)
  for lo,hi in [(x0p-350,x0p+350),(x0p-500,x0p+500),(x0p-700,x0p+700),(x0p-250,x0p+250)]:
    m=(x>=lo)&(x<=hi); xx=x[m]; yy=y[m]
    # guesses
    off0=np.percentile(yy,10)
    p0=[off0,amp,x0p,20]
    try:
        popt,pcov=curve_fit(lor,xx,yy,p0=p0,maxfev=20000)
        rmse=np.sqrt(np.mean((yy-lor(xx,*popt))**2))
        print(f'win {lo:.0f}-{hi:.0f} n{len(xx)} L(HWHM): off={popt[0]:.2f} A={popt[1]:.2f} x0={popt[2]:.3f} g={popt[3]:.3f} rmse={rmse:.2f}')
    except Exception as e: print('lor err',e)
    try:
        popt,pcov=curve_fit(lorF,xx,yy,p0=p0,maxfev=20000)
        rmse=np.sqrt(np.mean((yy-lorF(xx,*popt))**2))
        print(f'                    L(FWHM): off={popt[0]:.2f} A={popt[1]:.2f} x0={popt[2]:.3f} gamma={popt[3]:.3f} rmse={rmse:.2f}')
    except Exception as e: print('lorF err',e)
    try:
        popt,pcov=curve_fit(gau,xx,yy,p0=[off0,amp,x0p,30],maxfev=20000)
        rmse=np.sqrt(np.mean((yy-gau(xx,*popt))**2))
        print(f'                    G(sigma): off={popt[0]:.2f} A={popt[1]:.2f} x0={popt[2]:.3f} s={popt[3]:.3f} rmse={rmse:.2f}')
    except Exception as e: print('gau err',e)
    try:
        popt,pcov=curve_fit(pvoigt,xx,yy,p0=[off0,amp,x0p,80,0.5],maxfev=50000,bounds=([-np.inf,0,lo,0,0],[np.inf,np.inf,hi,1000,1]))
        rmse=np.sqrt(np.mean((yy-pvoigt(xx,*popt))**2))
        print(f'                    PV(FWHM): off={popt[0]:.2f} A={popt[1]:.2f} x0={popt[2]:.3f} w={popt[3]:.3f} eta={popt[4]:.3f} rmse={rmse:.2f}')
    except Exception as e: print('pv err',e)
    try:
        popt,pcov=curve_fit(linlor,xx,yy,p0=[off0,0,amp,x0p,20],maxfev=20000)
        rmse=np.sqrt(np.mean((yy-linlor(xx,*popt))**2))
        print(f'                    Lin+L: off={popt[0]:.2f} slope={popt[1]:.4f} A={popt[2]:.2f} x0={popt[3]:.3f} g={popt[4]:.3f} rmse={rmse:.2f}')
    except Exception as e: print('linlor err',e)
